package uz.mirix.tracelens.internal;import org.junit.jupiter.api.Test;import uz.mirix.tracelens.*;import java.util.Map;import static org.assertj.core.api.Assertions.assertThat;class TraceContextTest{@Test void buildsReportWithApplicationSelfTimeAndEnforcesSpanBudget(){TraceContext c=new TraceContext("GET","/api/orders/42",2);long b=c.startedNanos();c.record(TraceCategory.SQL,"SQL SELECT",b+1_000_000,b+4_000_000,Map.of());c.record(TraceCategory.HTTP,"HTTP GET inventory",b+5_000_000,b+9_000_000,Map.of());c.record(TraceCategory.REDIS,"Redis GET",b+10_000_000,b+11_000_000,Map.of());TraceReport r=c.finish("/api/orders/{id}",200,null,b+20_000_000);assertThat(r.route()).isEqualTo("/api/orders/{id}");assertThat(r.truncated()).isTrue();assertThat(r.spans()).hasSize(3);assertThat(r.spans().get(0).category()).isEqualTo(TraceCategory.APPLICATION);assertThat(r.spans().get(0).durationNanos()).isEqualTo(13_000_000);}@Test void mergesOverlappingIntervalsWhenCalculatingSelfTime(){TraceContext c=new TraceContext("GET","/",10);long b=c.startedNanos();c.record(TraceCategory.CUSTOM,"outer",b,b+8_000_000,Map.of());c.record(TraceCategory.SQL,"inner",b+2_000_000,b+4_000_000,Map.of());TraceReport r=c.finish("/",200,null,b+10_000_000);assertThat(r.spans().get(0).durationNanos()).isEqualTo(2_000_000);}}
